-- supabase/migrations/202610180001_drop_legacy_backtest_trades.sql  (next free version after 202610150005)
-- Drops the v1 table public.backtest_trades. Audit 2026-10-18: 0 rows, 0 users, 0 trades rows with
-- backtest markers, and no views, FKs, publications or user triggers depend on it.
-- Apply MANUALLY in the SQL Editor: schema_migrations is empty, so `supabase db push` would re-run all 35 files.
-- Deploy the client first without backtest_trades usage (src/pages/backtest.astro:516 and 519-537;
-- public/settings/js/settings.js:2359-2362). Until then the v1 page keeps inserting rows.
-- Recommended: run this in the same SQL Editor session/migration as the v2 CREATE TABLEs, so that
-- reset_user_data/delete_journal are replaced only once (see cleanup hooks).

BEGIN;

-- 0. Guard: refuse to drop if rows appeared after the audit.
DO $$
DECLARE
  v_rows bigint;
BEGIN
  IF to_regclass('public.backtest_trades') IS NOT NULL THEN
    EXECUTE 'LOCK TABLE public.backtest_trades IN ACCESS EXCLUSIVE MODE';
    EXECUTE 'SELECT count(*) FROM public.backtest_trades' INTO v_rows;
    IF v_rows > 0 THEN
      RAISE EXCEPTION 'public.backtest_trades has % row(s); archive or migrate them first', v_rows;
    END IF;
  END IF;
END
$$;

-- 1. reset_user_data: the LIVE body (pg_get_functiondef, byte-identical to 202610150003_ctrader_cursor_reset.sql:44-97)
--    with only live lines 18-21 (the guarded backtest_trades DELETE) removed and the step-1 comment adjusted.
--    Do NOT start from 202610030001_reset_user_data_rpc.sql: it lacks step 6 (cTrader cursor reset).
--    This step is not needed for correctness, because the old block is guarded by to_regclass and keeps
--    working after the DROP. It is cleanup.
CREATE OR REPLACE FUNCTION public.reset_user_data()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_default_jid UUID;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- 1. Trades (journal-exported backtest rows, import_hash LIKE 'backtest:%', are deleted here as well)
  DELETE FROM public.trades WHERE user_id = v_uid;

  -- 2. Stratejiler
  IF to_regclass('public.strategies') IS NOT NULL THEN
    DELETE FROM public.strategies WHERE user_id = v_uid;
  END IF;

  -- 3. Bildirimler
  IF to_regclass('public.notifications') IS NOT NULL THEN
    DELETE FROM public.notifications WHERE user_id = v_uid;
  END IF;

  -- 4. User Onboarding
  IF to_regclass('public.user_onboarding') IS NOT NULL THEN
    DELETE FROM public.user_onboarding WHERE user_id = v_uid;
  END IF;

  -- 5. Defterler (Journals)
  -- Özel defterleri sil, varsayılan defteri temizle/oluştur
  IF to_regclass('public.journals') IS NOT NULL THEN
    DELETE FROM public.journals WHERE user_id = v_uid AND is_default = false;

    SELECT id INTO v_default_jid FROM public.journals WHERE user_id = v_uid AND is_default = true LIMIT 1;
    IF v_default_jid IS NULL THEN
      INSERT INTO public.journals (user_id, name, description, color, icon, is_default, is_active)
      VALUES (v_uid, 'Ana Hesap', 'Varsayılan işlem günlüğü', '#7c6dfa', 'folder', true, true);
    ELSE
      UPDATE public.journals
      SET name = 'Ana Hesap', description = 'Varsayılan işlem günlüğü', color = '#7c6dfa', icon = 'folder', is_active = true
      WHERE id = v_default_jid;
    END IF;
  END IF;

  -- 6. cTrader senkron imleci: işlemler silindiği için bir sonraki senkron tüm geçmişi (en fazla 90 gün) yeniden
  --    getirsin (eskiden imleç korunuyor ve yalnızca son 2 gün geri geliyordu).
  IF to_regclass('public.ctrader_accounts') IS NOT NULL THEN
    UPDATE public.ctrader_accounts
    SET last_deal_timestamp = NULL, last_error = NULL, updated_at = now()
    WHERE user_id = v_uid;
  END IF;
END;
$function$;

-- The live ACL is EXECUTE for postgres, authenticated and service_role (no anon, no PUBLIC). CREATE OR REPLACE keeps it; re-assert anyway:
REVOKE ALL ON FUNCTION public.reset_user_data() FROM public;
GRANT EXECUTE ON FUNCTION public.reset_user_data() TO authenticated;

-- 2. Drop. Plain RESTRICT, so any unexpected dependent aborts the transaction. This also removes the 4 policies,
--    4 indexes, PK and FK (NO ACTION), the internal RI triggers, the grants and the types backtest_trades/_backtest_trades.
--    PostgREST reloads its cache through the pgrst_drop_watch event trigger.
DROP TABLE IF EXISTS public.backtest_trades;

COMMIT;

